mapper.select:
/* 내 즐겨찾기 조회 : 해제한 행 포함 */
SELECT B.PLC_BKMK_SN
     , B.PLC_SN
     , B.MBR_SN
     , B.USE_YN
     , B.REG_DT
     , B.MDFCN_DT
  FROM PLC_BKMK B
 WHERE B.MBR_SN = #{mbrSn}
   AND B.PLC_SN = #{plcSn}

mapper.insert:
/* 즐겨찾기 등록 */
INSERT INTO PLC_BKMK (PLC_SN, MBR_SN, USE_YN, REG_DT, MDFCN_DT)
VALUES (#{plcSn}, #{mbrSn}, 'Y', NOW(), NOW())

mapper.update:
/* 즐겨찾기 사용 여부 변경 */
UPDATE PLC_BKMK
   SET USE_YN   = #{toUseYn}
     , MDFCN_DT = NOW()
 WHERE PLC_BKMK_SN = #{plcBkmkSn}
   AND MBR_SN = #{mbrSn}
   AND USE_YN = #{fromUseYn}
